 if(p.travel){h+='<div class="card"><span class="label">Travel \u00b7 at cost</span><p class="body" style="margin:0.45rem 0 0.5rem;font-size:0.85rem;color:var(--faint)">'+esc(p.travel.note)+'</p>';p.travel.lines.forEach(function(l){h+=row(l.label,l.note,money(l.value));});h+=row('Travel subtotal',null,money(p.travel.subtotal),{strong:true})+'<p class="body" style="margin:0.9rem 0 0;font-size:0.79rem;color:var(--faint)">'+esc(p.travel.footnote)+'</p></div>';}
