function viewVendors(){return '<h2 class="sec">Preferred <em>vendors</em></h2><p class="intro">People we have worked beside and would hire ourselves. No commission, no obligation, just names we trust.</p>'+P.vendors.map(function(g){return '<div class="card"><span class="label">'+esc(g.group)+'</span>'+g.items.map(function(v){return '<div style="padding:0.85rem 0;border-top:1px solid var(--hair)"><h3 class="sub">'+esc(v.name)+'</h3><p style="margin:0.2rem 0 0;font-size:0.82rem;color:var(--gold-text)">'+esc(v.role)+'</p><p class="body" style="margin:0.45rem 0 0.5rem;font-size:0.87rem">'+esc(v.blurb)+'</p><div style="display:flex;flex-wrap:wrap;gap:0.9rem">'+v.links.map(function(l){return '<a href="'+esc(l.href)+'" style="font-size:0.82rem"'+(l.href.indexOf('http')===0?' target="_blank" rel="noreferrer"':'')+'>'+esc(l.label)+'</a>';}).join('')+'</div></div>';}).join('')+'</div>';}).join('');}
function viewEngagement(){var free=P.playbook.filter(function(p){return p.cost==='Free';}).length,h='<h2 class="sec">Engagement <em>recommendations</em></h2><p class="intro">'+P.playbookIntro.replace('{{free}}',free).replace('{{n}}',P.playbook.length)+'</p>';if(P.playbookLead)h+='<div class="card"><span class="label">'+esc(P.playbookLead.title)+'</span><p class="body" style="margin:0.5rem 0 0">'+esc(P.playbookLead.body)+'</p></div>';h+='<ol style="list-style:none;margin:0;padding:0">'+P.playbook.map(function(p,i){return '<li style="display:grid;grid-template-columns:2.1rem 1fr;gap:0.35rem 0.7rem;padding:1.35rem 0;'+(i===0?'':'border-top:1px solid var(--line)')+'"><span style="font-family:var(--head);font-weight:800;font-size:0.82rem;color:var(--gold-text);padding-top:0.2rem">'+String(i+1).padStart(2,'0')+'</span><div style="min-width:0"><div style="display:flex;justify-content:space-between;align-items:baseline;gap:0.9rem;flex-wrap:wrap"><h3 class="sub">'+esc(p.title)+'</h3><span class="tag" style="color:'+(p.cost==='Free'?'var(--gold-text)':'var(--faint)')+'">'+esc(p.cost)+'</span></div><p class="body" style="margin:0.55rem 0 0;font-size:0.89rem">'+esc(p.body)+'</p></div></li>';}).join('')+'</ol>';if(P.playbookClose)h+='<div class="card" style="margin-top:1.5rem"><span class="label">'+esc(P.playbookClose.title)+'</span><p class="body" style="margin:0.55rem 0 0">'+P.playbookClose.body+'</p></div>';return h;}
