var RATINGS=[[5,'Unforgettable'],[4,'Great'],[3,'Good'],[2,'Fair'],[1,'Not what we hoped']],PERMS=[['Yes','Yes, share it with my name'],['Yes but anonymously','Yes, but keep my name off it'],['No','Keep it private, this is just for you']];
